/**
 * The ringtone: a short, original chiptune phrase in square waves, the sound of 8-bit consoles,
 * looped while a call rings. Generated by Web Audio, so there is no file to host and no rights to
 * clear.
 */

/** Semitones from A4 (440 Hz); null is a rest. Two bars, bouncy, in C major. */
const MELODY: (number | null)[] = [
  3, 7, 10, 7, 12, 10, 7, null,
  5, 8, 12, 8, 15, 12, 10, null,
];
/** Eighth notes at about 160 bpm. */
const NOTE_SECONDS = 0.19;
const PAUSE_SECONDS = 1.2;
const VOLUME = 0.07;
/** Phones that cannot play sound before a tap still buzz. */
const VIBRATION_MS = [300, 200, 300];

export class Ringtone {
  private context?: AudioContext;
  private loop?: ReturnType<typeof setInterval>;

  constructor(private readonly createContext: () => AudioContext | undefined = defaultContext) {}

  get playing(): boolean {
    return this.loop !== undefined;
  }

  start(): void {
    if (this.loop) {
      return;
    }
    this.context ??= this.createContext();
    // Browsers keep audio suspended until the page was interacted with; then only the buzz plays.
    void this.context?.resume().catch(() => undefined);
    const phrase = MELODY.length * NOTE_SECONDS + PAUSE_SECONDS;
    this.ring();
    this.loop = setInterval(() => this.ring(), phrase * 1000);
  }

  stop(): void {
    if (this.loop) {
      clearInterval(this.loop);
      this.loop = undefined;
    }
    navigator.vibrate?.(0);
  }

  private ring(): void {
    navigator.vibrate?.(VIBRATION_MS);
    const context = this.context;
    if (!context || context.state !== 'running') {
      return;
    }
    const start = context.currentTime + 0.05;
    MELODY.forEach((semitones, index) => {
      if (semitones !== null) {
        this.note(context, 440 * 2 ** (semitones / 12), start + index * NOTE_SECONDS);
      }
    });
  }

  /** One staccato note: a quick attack and decay keeps square waves from sounding harsh. */
  private note(context: AudioContext, frequency: number, at: number): void {
    const oscillator = context.createOscillator();
    const gain = context.createGain();
    oscillator.type = 'square';
    oscillator.frequency.setValueAtTime(frequency, at);
    gain.gain.setValueAtTime(0, at);
    gain.gain.linearRampToValueAtTime(VOLUME, at + 0.01);
    gain.gain.exponentialRampToValueAtTime(0.001, at + NOTE_SECONDS * 0.9);
    oscillator.connect(gain).connect(context.destination);
    oscillator.start(at);
    oscillator.stop(at + NOTE_SECONDS);
  }
}

function defaultContext(): AudioContext | undefined {
  return typeof AudioContext === 'undefined' ? undefined : new AudioContext();
}
